import java.io.*;

public class Main {
    static int[] fenwick;
    static int n;

    static void update(int i, int delta) {
        for (; i <= n; i += i & (-i)) {
            fenwick[i] += delta;
        }
    }

    static long query(int i) {
        long sum = 0;
        for (; i > 0; i -= i & (-i)) {
            sum += fenwick[i];
        }
        return sum;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in, 1 << 16));
        st.nextToken();
        n = (int) st.nval;
        st.nextToken();
        int q = (int) st.nval;

        fenwick = new int[n + 1];
        int[] arr = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            st.nextToken();
            arr[i] = (int) st.nval;
            update(i, arr[i]);
        }

        StringBuilder sb = new StringBuilder();
        for (int e = 0; e < q; e++) {
            st.nextToken();
            int type = (int) st.nval;
            st.nextToken();
            int k = (int) st.nval;

            if (type == 0) {
                st.nextToken();
                int p = (int) st.nval;
                update(k, p - arr[k]);
                arr[k] = p;
            } else {
                sb.append(query(k)).append('\n');
            }
        }

        System.out.print(sb);
    }
}
